-- 0055_form_content_polish.sql
-- 0055 — پیراستن فرم‌ها: غیرفعال‌سازی دو فرم موازی (achenbach-practical با sdq-parent و
-- teacher-classroom با ce-sdq-t-v1 هم‌پوشان‌اند؛ نسخه‌های استاندارد SDQ موتور تشخیصی را تغذیه
-- می‌کنند)، افزودن لنگرهای توصیفی به ۴۳ فیلد مقیاسیِ بدون scaleLabels (رندر دکمهٔ ۰۱۲۳ خام)،
-- بازنویسی آیتم‌های بی‌فعل home_behavior، حذف ارجاع منسوخ به «کانرز» در quick-multi-v1،
-- و به‌روزرسانی عناوین/توضیحات چهار فرم جمع‌بندی + home_behavior (نقش «پایش دوره‌ای»).
-- منبع محتوا: scripts/task38/payloads/*.json (اعتبارسنجی‌شده توسط عامل اصلی — Task 38 / m132).
-- رویدادهای تاریخی دست‌نخورده می‌مانند (EVENT_SELECT بر اساس type_id است، نه liveness).

UPDATE case_event_types SET active = 0, updated_at = datetime('now') WHERE key IN ('achenbach-practical', 'teacher-classroom') AND active = 1;

UPDATE case_event_types SET title = 'پایش رفتار در خانه — فرم خانواده', description = 'چند جملهٔ کوتاه دربارهٔ رفتار فرزندتان در خانه — خواب، بازی، پیروی از قواعد و استفاده از موبایل. این فرم برای پایش دوره‌ای است و می‌تواند پیش از هر جلسهٔ پیگیری دوباره پر شود؛ نتیجه به مقایسهٔ هفته‌ها و سنجش اثر مداخله کمک می‌کند.', fields = '[{"key":"i1","label":"در طول روز بی‌قرار و پرجنب‌وجوش است","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","گاهی","زیاد","تقریباً هر روز"]},{"key":"i2","label":"با اعضای خانواده پرخاشگری یا لجبازی می‌کند","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","گاهی","زیاد","تقریباً هر روز"]},{"key":"i3","label":"دستورها را تا آخر پیگیری نمی‌کند و نیمه‌کاره رها می‌کند","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","گاهی","زیاد","تقریباً هر روز"]},{"key":"i4","label":"خواب راحتی ندارد یا شب‌ها بی‌قرار است","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","گاهی","زیاد","تقریباً هر روز"]},{"key":"i5","label":"از تکلیف و فعالیت‌های ساخت‌یافته فرار می‌کند","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","گاهی","زیاد","تقریباً هر روز"]},{"key":"i6","label":"سر استفاده از موبایل یا تلویزیون دعوا راه می‌اندازد","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","گاهی","زیاد","تقریباً هر روز"]},{"key":"i7","label":"با بزرگ‌ترها حرف تند می‌زند یا رفتار بی‌احترامی دارد","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","گاهی","زیاد","تقریباً هر روز"]},{"key":"i8","label":"شب‌ها نگرانی یا ترس‌های بی‌مورد دارد","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","گاهی","زیاد","تقریباً هر روز"]}]', bands = '[{"max":8,"label":"در محدودهٔ مطلوب","color":"ok","advice":"وضعیت خانه مطلوب است — پایش دوره‌ای را ادامه دهید."},{"max":16,"label":"نیاز به توجه و پیگیری","color":"warn","advice":"نشانه‌ها مرزی است؛ نتیجه را در جلسهٔ بعد با درمانگر در میان بگذارید."},{"max":24,"label":"نیاز به مداخلهٔ جدی","color":"danger","advice":"نشانه‌ها بالاست؛ حتماً با درمانگر پرونده هم‌گام‌سازی شود."}]', updated_at = datetime('now') WHERE key = 'home_behavior';

UPDATE case_event_types SET fields = '[{"key":"q1","label":"در جمع‌ها و موقعیت‌های جدید رفتار او بیشتر به کدام توصیف نزدیک است؟","type":"single","required":true,"subscaleId":"soc","scoredOptions":[{"label":"راحت است و سریع سازگار می‌شود","score":0},{"label":"ابتدا مضطرب اما به‌مرور راحت می‌شود","score":1},{"label":"اجتناب می‌کند یا می‌چسبد","score":2},{"label":"اصولاً قادر به حضور نیست","score":3}]},{"key":"q2","label":"حین انجام تکلیف، توجه او چقدر حفظ می‌شود؟","type":"single","required":true,"subscaleId":"att","scoredOptions":[{"label":"تا آخر کامل","score":0},{"label":"گاهی پرت می‌شود","score":1},{"label":"بیشتر وقت‌ها پرت است","score":2},{"label":"تقریباً هیچ‌وقت","score":3}]},{"key":"q3","label":"در نشستن طولانی بی‌قراری حرکتی دارد","type":"scale","scaleMax":3,"required":true,"subscaleId":"att","scaleLabels":["اصلاً","گاهی","زیاد","تقریباً همیشه"]},{"key":"q4","label":"بیشترین نگرانی او در روز چیست؟","type":"single","required":true,"subscaleId":"emo","scoredOptions":[{"label":"نگرانی خاصی ندارد","score":0},{"label":"مدرسه یا درس","score":1},{"label":"جدا شدن از والد","score":2},{"label":"چند موضوع هم‌زمان و شدید","score":3}]},{"key":"q5","label":"با هم‌سالانش همکاری و بازی گروهی دارد","type":"scale","scaleMax":2,"required":true,"subscaleId":"soc","reverse":true,"scaleLabels":["اصولاً نمی‌شود","تا حدی","بله، خوب"]},{"key":"q6","label":"آیا رفتاری که به خود یا دیگران آسیب می‌زند دیده‌اید؟","type":"single","required":true,"subscaleId":"beh","scoredOptions":[{"label":"هرگز","score":0},{"label":"لفظی و گاه‌به‌گاه","score":1},{"label":"لفظی و مکرر","score":2},{"label":"جسمی — به خود یا دیگری","score":3}],"critical":true,"criticalMin":3}]', bands = '[{"max":8,"label":"در محدودهٔ عادی","color":"ok","advice":"نمرهٔ غربال عادی است — در صورت نگرانی خاص، چک‌لیست تخصصی را بفرستید."},{"max":13,"label":"مرزی — نیاز به توجه","color":"warn","advice":"نمرهٔ مرزی؛ برای تکمیل ارزیابی، چک‌لیست‌های تخصصی SDQ و SNAP-IV پیشنهاد می‌شود."},{"max":9999,"label":"قابل توجه — نیاز به ارزیابی تخصصی","color":"danger","advice":"نمرهٔ غربال بالاست؛ ارزیابی تخصصی و مصاحبهٔ والدین لازم است."}]', updated_at = datetime('now') WHERE key = 'quick-multi-v1';

UPDATE case_event_types SET fields = '[{"key":"goal","label":"هدف جلسه","type":"text","required":true},{"key":"activities","label":"فعالیت‌های انجام‌شده","type":"longtext","required":true},{"key":"performance","label":"عملکرد کودک","type":"longtext"},{"key":"participation","label":"میزان مشارکت","type":"scale","scaleMax":5,"scaleLabels":["اصلاً مشارکت نمی‌کند","خیلی کم","کم","متوسط","خوب","فعال و مشتاق"]},{"key":"home_task","label":"تکلیف خانه","type":"text"},{"key":"recommendations","label":"توصیه به خانواده","type":"longtext"}]', updated_at = datetime('now') WHERE key = 'intervention';

UPDATE case_event_types SET title = 'جمع‌بندی شک بالینی پس از چک‌لیست‌ها', description = 'پس از بازبینی نتایج چک‌لیست‌های والد و معلم، شک بالینی فعلی، خلاصهٔ نتایج و تصمیم گام بعد را ثبت کنید. این جمع‌بندی در تایم‌لاین پرونده و گزارش کمیسیون استفاده می‌شود.', fields = '[{"key":"suspect","label":"شک بالینی فعلی","type":"select","options":["بیش‌فعالی/کم‌توجهی","اضطراب","بیش‌فعالی و اضطراب هم‌زمان","شک جدی ندارم"],"required":true},{"key":"signal_summary","label":"خلاصهٔ نتایج چک‌لیست‌ها","type":"text","placeholder":"مثلاً: SNAP-IV والد IA=۱۸ و معلم IA=۱۷ — هر دو پرخطر"},{"key":"decision","label":"تصمیم درمانگر در همین گام","type":"select","options":["ادامهٔ مسیر استاندارد (وکسلر و ارزیابی کامل)","شناسایی قطعی — ورود موازی به مداخله","بازبینی پس از مشاهدهٔ کلاس","ارجاع تخصصی (روان‌پزشک/روان‌شناس)"],"required":true},{"key":"note","label":"یادداشت بالینی","type":"longtext"}]', updated_at = datetime('now') WHERE key = 'ce-clinical-suspicion-v1';

UPDATE case_event_types SET title = 'گزارش نتایج ارزیابی', description = 'خلاصهٔ رسمی ارزیابی: ابزارهای انجام‌شده، یافته‌های کلیدی، نقاط قوت، دشواری‌های اولویت‌دار و اقدام بعدی. این گزارش پایهٔ جلسهٔ بازخورد با خانواده و سند کمیسیون پرونده است.', updated_at = datetime('now') WHERE key = 'ce-results-v1';

UPDATE case_event_types SET title = 'تعیین نیاز ویژه و پروتکل مداخله', description = 'با تکیه بر شواهد شناسایی، نوع نیاز ویژه و پروتکل مداخلهٔ اصلی (و در صورت نیاز پروتکل پشتیبان) را نهایی کنید؛ اهداف کوچک دورهٔ اول و برنامهٔ جلسات نیز اینجا ثبت می‌شود.', updated_at = datetime('now') WHERE key = 'ce-needs-v1';

UPDATE case_event_types SET title = 'گزارش جلسهٔ کاردرمانی ذهنی', description = 'حیطه‌های تمرکز، خلاصهٔ جلسه و واکنش کودک، و تمرین خانگی پیشنهادی جلسهٔ کاردرمانی ذهنی را ثبت کنید.', updated_at = datetime('now') WHERE key = 'ce-ot-session-v1';
